mapper.select:
SELECT prw.id, prw.CODE, prw.produce_order_no, prw.produce_order_id, pp.CODE AS process_no, pp.name AS processName, prw.station_id, prw.create_time, prw.start_time, prw.end_time, prw.create_name, prw.process_quantity, prw.badness_quantity, prw.unit_id, prw.batch_no, prw.classes_id, prw.class_group_id FROM pms_report_work prw JOIN pms_produce_order_craft pp ON pp.id = prw.process_id WHERE prw.del_flag = 0 AND pp.del_flag = 0
AND pp.name LIKE CONCAT('%',#{dto.processName},'%')
AND pp.produce_order_id =#{dto.produceOrderId}
AND prw.produce_order_no LIKE CONCAT('%',#{dto.produceOrderNo},'%')
AND prw.station_id = #{dto.stationId}
AND pp.id = #{dto.processId}
AND prw.classes_id = #{dto.classesId}
AND prw.create_time >= #{dto.createTimeStart}
AND prw.create_time <= #{dto.createTimeEnd}
AND prw.start_time >= #{dto.startTimeStart}
AND prw.start_time <= #{dto.startTimeEnd}
AND prw.end_time >= #{dto.endTimeStart}
AND prw.end_time <= #{dto.endTimeEnd}
order by prw.create_time desc

SELECT prw.product_line_id, prw.classes_id, prw.process_id, ppo.material_id, sum( prw.process_quantity ) as process_quantity, sum( prw.badness_quantity ) as badness_quantity FROM pms_report_work prw JOIN pms_produce_order ppo ON prw.produce_order_id = ppo.id WHERE prw.del_flag = 0 AND ppo.del_flag = 0
AND prw.classes_id in
#{classesId}
AND prw.product_line_id in
#{productLineId}
AND DATE_FORMAT(prw.create_time, '%Y-%m-%d' ) = #{date} GROUP BY prw.product_line_id, prw.classes_id, prw.process_id, ppo.material_id
